# 목록에서 빠진 파일 정리
KEEP="run walk weights yoga swim bike climb dance biceps soccer basketball tennis badminton baseball skate martial ballet sneaker hiking salad broccoli carrot tomato cucumber leafy avocado corn potato mushroom pepper onion garlic ginger apple banana grapes strawberry blueberry orange kiwi peach watermelon lemon olive herb rice soup bowl fish egg meat bread cheese nuts beans sandwich bento cutlery water milk tea coffee bottle honey sleep moon bath shower hotspring couch sunrise alarm soap toothbrush tooth broom lotion nosmoking heart lungs brain bone pill syringe stethoscope bandage hospital sun sprout plant tree mountain beach wave rainbow flower sunflower clover leaf cloud camping star sparkles fire trophy medal check memo notebook calendar chart target gift party stopwatch paw cat dog rabbit turtle bird butterfly bee greenheart growingheart meditate music book talk think hug handshake candle letter eye eyes ear nose glasses scale ski snowboard skateboard pingpong volleyball kite sushi riceball dumpling noodles sweetpotato shrimp crab butter salt cooking pot shopping croissant snow snowman rain wind bus train school office store wheelchair cane crutch hearingaid pregnant baby feeding toilet cake icecream cookie chocolate doughnut candy pie shavedice pudding camera movie art game travel luggage map group picnic cheers phoneoff smile relieved cool hearthands"
for f in assets/emoji/*.png; do
  [ -e "$f" ] || continue
  n=$(basename "$f" .png)
  case " $KEEP " in
    *" $n "*) ;;
    *) rm "$f"; echo "정리: $n" ;;
  esac
done

echo "완료: $(ls assets/emoji/*.png 2>/dev/null | wc -l) 개"
